import numpy as np

class Retriever:

    def __init__(self, arr, k):
        self.vectors = arr
        self.k = k

    def set_k(self, new_k):
        if (len(self.vectors) >= new_k) and (new_k > 0):
            self.k = new_k

    def add_vectors(self, new_vec):
        self.vectors = np.vstack((self.vectors, new_vec))

    def distance(self, query_vec):
        return np.linalg.norm(self.vectors - query_vec, axis=1)

    def get_top_k(self, query_vec):
        ans = sorted(self.distance(query_vec))
        return ans[:k+1]

    def get_similarity_matrix(self, query_vecs):
        return np.dot(self.vectors, query_vecs.T)
